/* hand-written; not generated. Databricks twin of dbt/models/tags/cost_unit_tag.sql: one row per */ /* (window_days, unit_id, level, tag_key, tag_value) -- the REAL tag values a tags.cost_unit row */ /* carries, the workspace level by the tag valid on each billed day (shared _workspace_history.sql */ /* block). 30 is filled in at export time. */ /* The base pipeline (priced/classified/wh_days/attr_days/split_factor/alloc_rows/keyed/hashed) is */ /* the SAME logic as tags/cost_unit.sql, duplicated on purpose (its own header note explains why): */ /* unit_id's hash formula must stay identical in both files, or a unit here fails to join back to */ /* cost_unit by unit_id. */ WITH wsh_billed /* hand-written; not generated. Databricks twin of dbt/models/tags/tag_workspace_history.sql, as CTEs */ /* only: tools/export_direct_results.py pastes it where a tags query says __WORKSPACE_HISTORY__, and */ /* that query reads ws_history -- one row per (workspace_id, tag_key, valid_from), the workspace's */ /* tag inferred per billed day from sysx.billing.usage.custom_tags. A run of days with one value */ /* is a version once it has held 3 days (to the next change, or to today); a shorter run stays in */ /* the version before it. The first version starts on the workspace's first billed day, so days */ /* before a tag first showed read '__untagged__'. valid_to is exclusive, NULL on the current row. */ AS (SELECT ROW_NUMBER() OVER () AS rid, u.workspace_id, u.usage_date, u.usage_quantity, u.custom_tags FROM "sysx"."billing"."usage" AS u WHERE u.usage_unit = 'DBU' AND NOT u.workspace_id IS NULL AND u.usage_date < CAST('2026-09-21' AS DATE) AND u.ingestion_date < CAST('2026-09-21' AS DATE) AND /* an Azure workspace tag reaches serverless usage as well as classic compute, and a usage */ /* policy's tags are the policy's, not the workspace's */ u.usage_metadata.budget_policy_id IS NULL AND u.usage_metadata.usage_policy_id IS NULL), wsh_day_totals AS (SELECT workspace_id, usage_date, SUM(usage_quantity) AS dbus_total FROM wsh_billed GROUP BY workspace_id, usage_date), wsh_pairs AS (/* one (row, normalised key) pair; when a map holds two spellings of one key, the */ /* alphabetically first raw key wins */ SELECT b.workspace_id, b.usage_date, b.usage_quantity, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM wsh_billed AS b CROSS JOIN LATERAL (SELECT unnest(map_keys(b.custom_tags)) AS raw_key, unnest(map_values(b.custom_tags)) AS raw_value) AS x WHERE NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY b.rid, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), wsh_day_values AS (SELECT workspace_id, tag_key, usage_date, tag_value, SUM(usage_quantity) AS dbus FROM wsh_pairs GROUP BY workspace_id, tag_key, usage_date, tag_value), wsh_day_top AS (SELECT workspace_id, tag_key, usage_date, tag_value, dbus, SUM(dbus) OVER (PARTITION BY workspace_id, tag_key, usage_date) AS dbus_tagged, ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key, usage_date ORDER BY dbus DESC, tag_value NULLS FIRST) AS rn FROM wsh_day_values), wsh_day_state AS (/* every billed day of the workspace for every key it ever carried */ SELECT k.workspace_id, k.tag_key, t.usage_date, CASE WHEN d.dbus_tagged IS NULL OR d.dbus_tagged / NULLIF(t.dbus_total, 0) < 0.5 OR t.dbus_total <= 0 THEN '__untagged__' WHEN d.dbus / NULLIF(d.dbus_tagged, 0) >= 0.6 THEN d.tag_value ELSE '__mixed__' END AS state FROM (SELECT DISTINCT workspace_id, tag_key FROM wsh_day_values) AS k JOIN wsh_day_totals AS t ON t.workspace_id = k.workspace_id LEFT JOIN wsh_day_top AS d ON d.workspace_id = k.workspace_id AND d.tag_key = k.tag_key AND d.usage_date = t.usage_date AND d.rn = 1), wsh_runs AS (SELECT workspace_id, tag_key, state, MIN(usage_date) AS run_from FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key ORDER BY usage_date NULLS FIRST) - ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key, state ORDER BY usage_date NULLS FIRST) AS grp FROM wsh_day_state) AS d GROUP BY workspace_id, tag_key, state, grp), wsh_kept AS (/* a run stands once it has held 3 days, counted to the next run or to today */ SELECT *, CASE WHEN DATE_DIFF('DAY', run_from, COALESCE(LEAD(run_from) OVER (PARTITION BY workspace_id, tag_key ORDER BY run_from NULLS FIRST), CAST('2026-09-21' AS DATE))) >= 3 THEN state END AS kept_state FROM wsh_runs), wsh_smoothed AS (/* a short run takes the value of the last run that stands before it; a short first run keeps its own */ SELECT workspace_id, tag_key, run_from, COALESCE(kept_state, LAST_VALUE(kept_state IGNORE NULLS) OVER (PARTITION BY workspace_id, tag_key ORDER BY run_from NULLS FIRST ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), state) AS state FROM wsh_kept), wsh_versions AS (SELECT workspace_id, tag_key, state AS tag_value, MIN(run_from) AS valid_from FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key ORDER BY run_from NULLS FIRST) - ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key, state ORDER BY run_from NULLS FIRST) AS grp FROM wsh_smoothed) AS s GROUP BY workspace_id, tag_key, state, grp), wsh_dated AS (SELECT *, LEAD(valid_from) OVER (PARTITION BY workspace_id, tag_key ORDER BY valid_from NULLS FIRST) AS valid_to FROM wsh_versions), wsh_version_values AS (SELECT v.workspace_id, v.tag_key, v.valid_from, d.tag_value, SUM(d.dbus) AS dbus FROM wsh_dated AS v JOIN wsh_day_values AS d ON d.workspace_id = v.workspace_id AND d.tag_key = v.tag_key AND d.usage_date >= v.valid_from AND (v.valid_to IS NULL OR d.usage_date < v.valid_to) GROUP BY v.workspace_id, v.tag_key, v.valid_from, d.tag_value), wsh_version_ranked AS (SELECT *, SUM(dbus) OVER (PARTITION BY workspace_id, tag_key, valid_from) AS dbus_tagged, ROW_NUMBER() OVER (PARTITION BY workspace_id, tag_key, valid_from ORDER BY dbus DESC, tag_value NULLS FIRST) AS rn FROM wsh_version_values), wsh_top_values AS (SELECT workspace_id, tag_key, valid_from, LIST_TRANSFORM(ARRAY_SORT(ARRAY_AGG({'rn': rn, 'v': tag_value}) FILTER(WHERE {'rn': rn, 'v': tag_value} IS NOT NULL)), x -> x.v) AS top_values FROM wsh_version_ranked WHERE rn <= 5 GROUP BY workspace_id, tag_key, valid_from), wsh_version_totals AS (SELECT v.workspace_id, v.tag_key, v.valid_from, SUM(t.dbus_total) AS dbus_total FROM wsh_dated AS v JOIN wsh_day_totals AS t ON t.workspace_id = v.workspace_id AND t.usage_date >= v.valid_from AND (v.valid_to IS NULL OR t.usage_date < v.valid_to) GROUP BY v.workspace_id, v.tag_key, v.valid_from), wsh_display AS (/* the raw spelling carrying the most DBUs account-wide names the key on screen */ SELECT tag_key, raw_key AS display_key FROM (SELECT tag_key, raw_key, ROW_NUMBER() OVER (PARTITION BY tag_key ORDER BY SUM(usage_quantity) DESC, raw_key NULLS FIRST) AS rn FROM wsh_pairs GROUP BY tag_key, raw_key) AS d WHERE rn = 1), wsh_measured AS (SELECT v.workspace_id, v.tag_key, d.display_key, v.tag_value, v.valid_from, v.valid_to, r.tag_value AS top_value, tv.top_values, r.dbus / NULLIF(r.dbus_tagged, 0) AS share, COALESCE(r.dbus_tagged, 0) / NULLIF(t.dbus_total, 0) AS coverage, COALESCE(r.dbus_tagged, 0) AS dbus_tagged, t.dbus_total, CASE WHEN v.valid_to IS NULL THEN 'since ' || CAST(v.valid_from AS TEXT) ELSE 'from ' || CAST(v.valid_from AS TEXT) || ' to ' || CAST(CAST(v.valid_to AS DATE) + INTERVAL (1 * -1) DAY AS TEXT) END AS period FROM wsh_dated AS v JOIN wsh_version_totals AS t ON t.workspace_id = v.workspace_id AND t.tag_key = v.tag_key AND t.valid_from = v.valid_from JOIN wsh_display AS d ON d.tag_key = v.tag_key LEFT JOIN wsh_version_ranked AS r ON r.workspace_id = v.workspace_id AND r.tag_key = v.tag_key AND r.valid_from = v.valid_from AND r.rn = 1 LEFT JOIN wsh_top_values AS tv ON tv.workspace_id = v.workspace_id AND tv.tag_key = v.tag_key AND tv.valid_from = v.valid_from), ws_history AS (SELECT workspace_id, tag_key, display_key, tag_value, NOT tag_value IN ('__mixed__', '__untagged__') AS is_allocating, valid_from, valid_to, valid_to IS NULL AS is_current, top_value, top_values, share, coverage, dbus_tagged, dbus_total, CASE WHEN top_value IS NULL THEN period || ': no billed usage of this workspace carries ' || display_key WHEN tag_value = '__untagged__' THEN period || ': only ' || CAST(ROUND(COALESCE(coverage, 0) * 100, 1) AS TEXT) || '% of this workspace''s billed DBUs carry ' || display_key || ' (top value "' || top_value || '"); at least 50.0% is needed to infer a workspace tag' WHEN tag_value = '__mixed__' THEN period || ': no single ' || display_key || ' value reaches 60.0% of the ' || display_key || '-tagged DBUs (top "' || top_value || '" at ' || CAST(ROUND(share * 100, 1) AS TEXT) || '%); tagged DBUs are ' || CAST(ROUND(coverage * 100, 1) AS TEXT) || '% of this workspace''s billed DBUs' ELSE period || ': ' || display_key || ' "' || tag_value || '" carries ' || CAST(ROUND(share * 100, 1) AS TEXT) || '% of the ' || display_key || '-tagged DBUs, which are ' || CAST(ROUND(coverage * 100, 1) AS TEXT) || '% of this workspace''s billed DBUs' END AS reason FROM wsh_measured), priced AS (SELECT 30 AS window_days, u.workspace_id, u.usage_date, u.usage_unit, u.usage_quantity, u.custom_tags, u.usage_metadata, u.product_features, lp.list_rate FROM "sysx"."billing"."usage" AS u LEFT JOIN (SELECT sku_name, cloud, usage_unit, price_start_time, price_end_time, CAST(pricing.effective_list."default" AS DOUBLE) AS list_rate FROM "sysx"."billing"."list_prices") AS lp ON u.sku_name = lp.sku_name AND u.cloud = lp.cloud AND u.usage_unit = lp.usage_unit AND u.usage_end_time >= lp.price_start_time AND (lp.price_end_time IS NULL OR u.usage_end_time < lp.price_end_time) WHERE u.usage_date >= CAST('2026-09-21' AS DATE) - INTERVAL '30' DAYS AND u.usage_date < CAST('2026-09-21' AS DATE) AND u.ingestion_date < CAST('2026-09-21' AS DATE)), classified AS (SELECT window_days, workspace_id, usage_date, usage_unit, usage_quantity, custom_tags, list_rate, usage_metadata.warehouse_id AS warehouse_id, usage_metadata.job_id AS job_id, usage_metadata.dlt_pipeline_id AS dlt_pipeline_id, CASE WHEN NOT usage_metadata.warehouse_id IS NULL THEN 'warehouse' WHEN NOT usage_metadata.cluster_id IS NULL THEN 'cluster' WHEN NOT usage_metadata.endpoint_id IS NULL OR NOT usage_metadata.endpoint_name IS NULL THEN 'endpoint' WHEN NOT usage_metadata.app_id IS NULL THEN 'app' WHEN NOT usage_metadata.job_id IS NULL OR NOT usage_metadata.dlt_pipeline_id IS NULL OR NOT usage_metadata.notebook_id IS NULL OR NOT usage_metadata.budget_policy_id IS NULL OR NOT usage_metadata.usage_policy_id IS NULL OR product_features.is_serverless IS TRUE THEN 'serverless' ELSE 'other' END AS compute_kind, COALESCE(usage_metadata.warehouse_id, usage_metadata.cluster_id, usage_metadata.endpoint_id, usage_metadata.endpoint_name, usage_metadata.app_id, usage_metadata.budget_policy_id, usage_metadata.usage_policy_id) AS compute_id FROM priced), wh_days AS (SELECT window_days, workspace_id, warehouse_id, usage_date, SUM(usage_quantity) AS billed_dbus FROM classified WHERE compute_kind = 'warehouse' AND usage_unit = 'DBU' GROUP BY window_days, workspace_id, warehouse_id, usage_date), attr_days AS (SELECT 30 AS window_days, a.workspace_id, a.usage_metadata.warehouse_id AS warehouse_id, a.usage_date, SUM(a.active_usage_quantity) AS attributed_dbus FROM "sysx"."billing"."attributed_usage" AS a WHERE a.usage_date >= CAST('2026-09-21' AS DATE) - INTERVAL '30' DAYS AND a.usage_date < CAST('2026-09-21' AS DATE) AND NOT a.usage_metadata.warehouse_id IS NULL GROUP BY a.workspace_id, a.usage_metadata.warehouse_id, a.usage_date), split_factor AS (SELECT wd.window_days, wd.workspace_id, wd.warehouse_id, wd.usage_date, wd.billed_dbus, COALESCE(ad.attributed_dbus, 0) AS attributed_dbus, CASE WHEN wd.billed_dbus > 0 AND COALESCE(ad.attributed_dbus, 0) > 0 THEN LEAST(ad.attributed_dbus, wd.billed_dbus) / wd.billed_dbus ELSE 0 END AS split_f FROM wh_days AS wd LEFT JOIN attr_days AS ad ON ad.window_days = wd.window_days AND ad.workspace_id = wd.workspace_id AND ad.warehouse_id = wd.warehouse_id AND ad.usage_date = wd.usage_date), alloc_rows AS (/* query-part rows keep usage_date and compute_id (=warehouse_id): the per-day grain the */ /* attributed-tag-value proportional split below needs. */ SELECT c.window_days, c.workspace_id, c.usage_date, c.compute_kind, c.compute_id, c.custom_tags, c.usage_unit, 'query' AS work_kind, CAST(NULL AS TEXT) AS work_id, CASE WHEN NOT c.list_rate IS NULL THEN c.usage_quantity * sf.split_f * c.list_rate END AS part_usd FROM classified AS c JOIN split_factor AS sf ON sf.window_days = c.window_days AND sf.workspace_id = c.workspace_id AND sf.warehouse_id = c.warehouse_id AND sf.usage_date = c.usage_date WHERE c.compute_kind = 'warehouse' AND c.usage_unit = 'DBU' AND sf.split_f > 0 UNION ALL SELECT c.window_days, c.workspace_id, c.usage_date, c.compute_kind, c.compute_id, c.custom_tags, c.usage_unit, CASE WHEN sf.attributed_dbus > 0 THEN 'warehouse_idle' ELSE 'warehouse_unsplit' END AS work_kind, CAST(NULL AS TEXT) AS work_id, CASE WHEN NOT c.list_rate IS NULL THEN c.usage_quantity * (1 - sf.split_f) * c.list_rate END AS part_usd FROM classified AS c JOIN split_factor AS sf ON sf.window_days = c.window_days AND sf.workspace_id = c.workspace_id AND sf.warehouse_id = c.warehouse_id AND sf.usage_date = c.usage_date WHERE c.compute_kind = 'warehouse' AND c.usage_unit = 'DBU' AND (1 - sf.split_f) > 0 UNION ALL SELECT c.window_days, c.workspace_id, c.usage_date, c.compute_kind, c.compute_id, c.custom_tags, c.usage_unit, CASE WHEN NOT c.job_id IS NULL THEN 'job' WHEN NOT c.dlt_pipeline_id IS NULL THEN 'pipeline' ELSE 'none' END AS work_kind, COALESCE(c.job_id, c.dlt_pipeline_id) AS work_id, CASE WHEN NOT c.list_rate IS NULL THEN c.usage_quantity * c.list_rate END AS part_usd FROM classified AS c WHERE NOT (c.compute_kind = 'warehouse' AND c.usage_unit = 'DBU')), keyed AS (SELECT r.*, CASE WHEN r.custom_tags IS NULL OR cardinality() = 0 THEN NULL ELSE ARRAY_TO_STRING(ARRAY_SORT(LIST_TRANSFORM(MAP_ENTRIES(r.custom_tags), e -> e.key || '=' || e.value)), ',') END AS tags_key FROM alloc_rows AS r), hashed AS (SELECT *, MD5(COALESCE(workspace_id, '~') || '|' || compute_kind || '|' || COALESCE(compute_id, '~') || '|' || work_kind || '|' || COALESCE(work_id, '~') || '|' || usage_unit || '|' || COALESCE(tags_key, '~')) AS unit_id FROM keyed), unit_totals /* --------------------------------------------------------------------------------------------- */ /* Compute level: the unit's OWN custom_tags map, exploded (dedup per normalised key). usd = the */ /* whole unit's usd. */ /* --------------------------------------------------------------------------------------------- */ AS (SELECT window_days, unit_id, ANY_VALUE(compute_kind) AS compute_kind, ANY_VALUE(compute_id) AS compute_id, ANY_VALUE(custom_tags) AS custom_tags, COALESCE(SUM(part_usd), 0) AS usd FROM hashed GROUP BY window_days, unit_id), compute_pairs AS (SELECT ut.window_days, ut.unit_id, ut.compute_kind, ut.compute_id, ut.usd, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM unit_totals AS ut CROSS JOIN LATERAL (SELECT unnest(map_keys(ut.custom_tags)) AS raw_key, unnest(map_values(ut.custom_tags)) AS raw_value) AS x WHERE NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY ut.window_days, ut.unit_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), compute_level AS (SELECT window_days, unit_id, 'compute' AS level, tag_key, raw_key, tag_value, CASE WHEN compute_kind = 'warehouse' THEN 'billing:warehouse' WHEN compute_kind = 'cluster' THEN 'billing:cluster' WHEN compute_kind = 'endpoint' THEN 'billing:endpoint' WHEN compute_kind = 'app' THEN 'billing:app' WHEN compute_kind = 'serverless' AND NOT compute_id IS NULL THEN 'billing:budget_policy' WHEN compute_kind = 'serverless' THEN 'billing:serverless' ELSE 'billing:other' END AS source, usd FROM compute_pairs), workspace_level /* --------------------------------------------------------------------------------------------- */ /* Workspace level: the workspace's own tag on each billed day. */ /* --------------------------------------------------------------------------------------------- */ AS (SELECT h.window_days, h.unit_id, 'workspace' AS level, wh.tag_key, wh.display_key AS raw_key, wh.tag_value, 'workspace_inferred' AS source, COALESCE(SUM(h.part_usd), 0) AS usd FROM hashed AS h JOIN ws_history AS wh ON wh.workspace_id = h.workspace_id AND wh.is_allocating AND h.usage_date >= wh.valid_from AND (wh.valid_to IS NULL OR h.usage_date < wh.valid_to) GROUP BY h.window_days, h.unit_id, wh.tag_key, wh.display_key, wh.tag_value), work_jp_units /* --------------------------------------------------------------------------------------------- */ /* Work level, job/pipeline units: the job's/pipeline's own LATEST tags (lakeflow), not the bill. */ /* --------------------------------------------------------------------------------------------- */ AS (SELECT window_days, unit_id, ANY_VALUE(workspace_id) AS workspace_id, ANY_VALUE(work_kind) AS work_kind, ANY_VALUE(work_id) AS work_id, COALESCE(SUM(part_usd), 0) AS usd FROM hashed WHERE work_kind IN ('job', 'pipeline') GROUP BY window_days, unit_id), job_tags_latest AS (SELECT workspace_id, job_id, tags FROM (SELECT workspace_id, job_id, tags, ROW_NUMBER() OVER (PARTITION BY workspace_id, job_id ORDER BY change_time DESC) AS rn FROM "sysx"."lakeflow"."jobs") AS x WHERE rn = 1), pipeline_tags_latest AS (SELECT workspace_id, pipeline_id, tags FROM (SELECT workspace_id, pipeline_id, tags, ROW_NUMBER() OVER (PARTITION BY workspace_id, pipeline_id ORDER BY change_time DESC) AS rn FROM "sysx"."lakeflow"."pipelines") AS x WHERE rn = 1), work_job_pairs AS (SELECT u.window_days, u.unit_id, u.usd, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value, 'job_tags' AS source FROM work_jp_units AS u JOIN job_tags_latest AS jt ON jt.workspace_id = u.workspace_id AND jt.job_id = u.work_id CROSS JOIN LATERAL (SELECT unnest(map_keys(jt.tags)) AS raw_key, unnest(map_values(jt.tags)) AS raw_value) AS x WHERE u.work_kind = 'job' AND NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY u.window_days, u.unit_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), work_pipeline_pairs AS (SELECT u.window_days, u.unit_id, u.usd, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value, 'pipeline_tags' AS source FROM work_jp_units AS u JOIN pipeline_tags_latest AS pt ON pt.workspace_id = u.workspace_id AND pt.pipeline_id = u.work_id CROSS JOIN LATERAL (SELECT unnest(map_keys(pt.tags)) AS raw_key, unnest(map_values(pt.tags)) AS raw_value) AS x WHERE u.work_kind = 'pipeline' AND NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY u.window_days, u.unit_id, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), work_jp_level AS (SELECT window_days, unit_id, 'work' AS level, tag_key, raw_key, tag_value, source, usd FROM work_job_pairs UNION ALL SELECT window_days, unit_id, 'work' AS level, tag_key, raw_key, tag_value, source, usd FROM work_pipeline_pairs), query_alloc_by_day /* --------------------------------------------------------------------------------------------- */ /* Work level, query units: split each day's query-part $ across the attributed statements' own */ /* query_tags, in proportion to their attributed DBUs for that day. attributed_query_tags is */ /* always the source -- Databricks' own per-query cost split, never the resource's current tags. */ /* --------------------------------------------------------------------------------------------- */ AS (SELECT window_days, unit_id, workspace_id, compute_id AS warehouse_id, usage_date, SUM(part_usd) AS day_usd FROM hashed WHERE work_kind = 'query' GROUP BY window_days, unit_id, workspace_id, compute_id, usage_date), attr_rows AS (SELECT 30 AS window_days, ROW_NUMBER() OVER () AS arid, a.workspace_id, a.usage_metadata.warehouse_id AS warehouse_id, a.usage_date, a.active_usage_quantity, a.granular_tags.query_tags AS query_tags FROM "sysx"."billing"."attributed_usage" AS a WHERE a.usage_date >= CAST('2026-09-21' AS DATE) - INTERVAL '30' DAYS AND a.usage_date < CAST('2026-09-21' AS DATE) AND NOT a.usage_metadata.warehouse_id IS NULL), attr_pairs AS (SELECT ar.window_days, ar.arid, ar.workspace_id, ar.warehouse_id, ar.usage_date, ar.active_usage_quantity, raw_key, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') AS tag_key, TRIM(raw_value) AS tag_value FROM attr_rows AS ar CROSS JOIN LATERAL (SELECT unnest(map_keys(ar.query_tags)) AS raw_key, unnest(map_values(ar.query_tags)) AS raw_value) AS x WHERE NOT raw_key IS NULL AND NOT raw_value IS NULL AND REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') <> '' QUALIFY ROW_NUMBER() OVER (PARTITION BY ar.window_days, ar.arid, REGEXP_REPLACE(LOWER(raw_key), '[ _-]+', '', 'g') ORDER BY raw_key NULLS FIRST) = 1), attr_value_by_day AS (/* A(K=V) per (workspace, warehouse, usage_date) */ SELECT window_days, workspace_id, warehouse_id, usage_date, tag_key, ANY_VALUE(raw_key) AS raw_key, tag_value, SUM(active_usage_quantity) AS a_kv FROM attr_pairs GROUP BY window_days, workspace_id, warehouse_id, usage_date, tag_key, tag_value), query_tag_alloc AS (SELECT qd.window_days, qd.unit_id, v.tag_key, v.raw_key, v.tag_value, qd.day_usd * v.a_kv / NULLIF(ad.attributed_dbus, 0) AS part_usd FROM query_alloc_by_day AS qd JOIN attr_days AS ad ON ad.window_days = qd.window_days AND ad.workspace_id = qd.workspace_id AND ad.warehouse_id = qd.warehouse_id AND ad.usage_date = qd.usage_date JOIN attr_value_by_day AS v ON v.window_days = qd.window_days AND v.workspace_id = qd.workspace_id AND v.warehouse_id = qd.warehouse_id AND v.usage_date = qd.usage_date), query_tag_level AS (SELECT window_days, unit_id, 'work' AS level, tag_key, ANY_VALUE(raw_key) AS raw_key, tag_value, 'attributed_query_tags' AS source, SUM(part_usd) AS usd FROM query_tag_alloc GROUP BY window_days, unit_id, tag_key, tag_value) SELECT window_days, unit_id, level, tag_key, raw_key, tag_value, source, usd FROM compute_level WHERE usd <> 0 UNION ALL SELECT window_days, unit_id, level, tag_key, raw_key, tag_value, source, usd FROM work_jp_level WHERE usd <> 0 UNION ALL SELECT window_days, unit_id, level, tag_key, raw_key, tag_value, source, usd FROM query_tag_level WHERE usd <> 0 UNION ALL SELECT window_days, unit_id, level, tag_key, raw_key, tag_value, source, usd FROM workspace_level WHERE usd <> 0